def test_prompts_style_handling_uses_stream(stream, err, expect_styled, monkeypatch):
    """Outside ``CliRunner``, prompt styles are only kept when the stream the
    prompt goes to looks like a terminal, mirroring :func:`click.echo`.
    """
    received: list[str] = []

    def capture(text: str) -> str:
        received.append(text)
        return "y"

    if expect_styled:
        new_stream = _AlwaysTTY()
    else:
        new_stream = StringIO()

    monkeypatch.setattr("click.termui.visible_prompt_func", capture)
    monkeypatch.setattr(sys, stream, new_stream)

